"""Idempotent complete mapping for two Primary 6 text-layer papers."""
from pathlib import Path
import runpy
ROOT=Path(__file__).resolve().parents[2]
write_topic=runpy.run_path(str(Path(__file__).with_name('sheet_digestion_primary1.py')))['write_topic']
SOURCES=('mathematics/level/primary-6/4904-6-2567-2-2.pdf','mathematics/level/primary-6/4907-6-2567-2-2.pdf')
GROUPS=[('ratio-and-scale', 'อัตราส่วนและมาตราส่วน', [(1, 'ratio-meaning', 'ตีความอัตราส่วนเป็นการเปรียบเทียบสองปริมาณ', ['write_ratio_p6']), (2, 'write-ratio', 'เขียนอัตราส่วนตามลำดับปริมาณและจำนวนในภาพ', ['write_ratio_p6']), (3, 'shaded-ratio', 'นับส่วนแรเงาและไม่แรเงาก่อนเขียนอัตราส่วน', ['write_ratio_p6']), (4, 'quantity-ratio', 'เขียนอัตราส่วนปริมาณต่างชนิดโดยคงลำดับที่ถาม', ['write_ratio_p6']), (5, 'quantity-ratio', 'เขียนอัตราส่วนปริมาณต่างชนิดโดยคงลำดับที่ถาม', ['write_ratio_p6']), (6, 'reduce-ratio', 'หารทั้งสองจำนวนด้วยตัวหารร่วมเพื่อหาอัตราส่วนอย่างต่ำ', ['ratio_lowest_terms_p6']), (7, 'odd-ratio', 'เปรียบเทียบผลคูณไขว้เพื่อหาอัตราส่วนที่ไม่เท่ากัน', ['non_equivalent_ratio_p6']), (10, 'unit-price', 'ใช้สัดส่วนราคากับจำนวนสิ่งของเพื่อหาจำนวนที่ซื้อได้', ['ratio_word_problem_p6']), (11, 'principal-interest', 'ใช้อัตราดอกเบี้ยหนึ่งปีต่อเงินต้นร้อยหน่วยเพื่อเขียนอัตราส่วนอย่างต่ำ', ['principal_interest_ratio_p6'])]), ('percentages', 'ร้อยละ', [(8, 'ratio-percent', 'เปลี่ยนอัตราส่วนเป็นเศษส่วนของทั้งหมดแล้วคูณหนึ่งร้อย', ['ratio_to_percent']), (9, 'percent-ratio', 'เขียนร้อยละเป็นอัตราส่วนต่อร้อยแล้วลดรูป', ['percent_to_ratio']), (12, 'loss-amount', 'คูณต้นทุนด้วยอัตราขาดทุนหารร้อยเพื่อหาจำนวนเงินขาดทุน', ['percent_part_sentence_p5']), (13, 'inverse-profit', 'หารราคาขายด้วยหนึ่งบวกอัตรากำไรเพื่อย้อนหาทุน', ['cost_from_profit_p6']), (14, 'calendar-percent', 'ใช้จำนวนวันที่ทำงานหารจำนวนวันในเดือนที่ระบุแล้วคูณหนึ่งร้อย', ['calendar_percent_sentence_p6']), (15, 'simple-interest', 'หาดอกเบี้ยอย่างง่ายหนึ่งปีแล้วรวมกับเงินต้น', ['simple_interest']), (16, 'inverse-loss', 'หารราคาขายด้วยหนึ่งลบอัตราขาดทุนเพื่อย้อนหาทุนโดยคงค่าแน่นอน', ['cost_from_loss_sentence_p5'])]), ('pie-charts', 'แผนภูมิรูปวงกลม', [(17, 'missing-sector', 'ลบร้อยละของส่วนที่ทราบออกจากหนึ่งร้อย', ['pie_missing_percent_p6']), (18, 'sector-amount', 'คูณจำนวนทั้งหมดด้วยร้อยละของส่วนที่ถามหารร้อย', ['pie_chart_amount_p6']), (19, 'sector-difference', 'หาร้อยละส่วนต่างของสองประเภทแล้วคูณจำนวนทั้งหมด', ['percent_share_difference_p5']), (20, 'rank-sectors', 'เรียงค่าร้อยละทุกประเภทเพื่อระบุอันดับที่ถาม', ['table_order_p3'])]), ('gcd-and-lcm', 'ห.ร.ม. และ ค.ร.น.', [(21, 'factor-product-gcd', 'เลือกตัวประกอบเฉพาะร่วมที่มีเลขชี้กำลังน้อยที่สุดเพื่อหาความยาวแบ่งได้ลงตัวมากที่สุด', ['gcd_lcm_product_model_p6']), (22, 'factor-product-gcd', 'เลือกตัวประกอบเฉพาะร่วมที่มีเลขชี้กำลังน้อยที่สุดเพื่อหาความยาวแบ่งได้ลงตัวมากที่สุด', ['gcd_lcm_product_model_p6']), (23, 'factor-product-lcm', 'เลือกตัวประกอบเฉพาะที่มีเลขชี้กำลังมากที่สุดเพื่อหาจำนวนร่วมบวกน้อยที่สุด', ['gcd_lcm_product_model_p6']), (24, 'factor-product-lcm', 'เลือกตัวประกอบเฉพาะที่มีเลขชี้กำลังมากที่สุดเพื่อหาจำนวนร่วมบวกน้อยที่สุด', ['gcd_lcm_product_model_p6'])]), ('patterns', 'แบบรูป', [(25, 'linear-figure-pattern', 'นับจำนวนในแบบรูปภาพแล้วใช้ผลต่างคงที่หาพจน์ที่กำหนด', ['pattern_nth_term_p6']), (26, 'constant-difference', 'หาผลต่างระหว่างพจน์ติดกันเพื่อบอกกฎเพิ่มหรือลด', ['pattern_next_term_p6']), (27, 'product-pattern', 'เขียนแต่ละพจน์เป็นผลคูณสองจำนวนที่เพิ่มเท่ากันแล้วหาคู่ตัวประกอบถัดไป', ['quadratic_product_pattern_p6'])]), ('solids', 'รูปเรขาคณิต 3 มิติ', [(28, 'pyramid-name', 'ใช้รูปฐานและหน้าข้างระบุชนิดพีระมิด', ['solid_from_description_p6']), (29, 'object-solid', 'เชื่อมรูปทรงวัตถุในชีวิตประจำวันกับทรงกระบอก', ['objects_as_solids_p6']), (30, 'pyramid-lateral', 'จำแนกหน้าข้างพีระมิดเป็นรูปสามเหลี่ยม', ['pyramid_counts_p6']), (31, 'axial-section', 'ระนาบผ่านแกนทรงกระบอกตรงให้หน้าตัดสี่เหลี่ยมผืนผ้ากว้างเท่าเส้นผ่านศูนย์กลาง', ['axial_cylinder_section_p6']), (32, 'net-solid', 'ใช้ชนิดและจำนวนหน้าของรูปคลี่เพื่อระบุรูปทรงโดยตรวจการประกอบ', ['net_to_solid_p6']), (33, 'net-solid', 'ใช้ชนิดและจำนวนหน้าของรูปคลี่เพื่อระบุรูปทรงโดยตรวจการประกอบ', ['net_to_solid_p6']), (34, 'net-solid', 'ใช้ชนิดและจำนวนหน้าของรูปคลี่เพื่อระบุรูปทรงโดยตรวจการประกอบ', ['net_to_solid_p6']), (35, 'net-solid', 'ใช้ชนิดและจำนวนหน้าของรูปคลี่เพื่อระบุรูปทรงโดยตรวจการประกอบ', ['net_to_solid_p6'])]), ('volume-and-surface-area', 'ปริมาตรและพื้นที่ผิว', [(36, 'box-volume-model', 'เลือกนิพจน์กว้างคูณยาวคูณสูงในหน่วยเดียวกัน', ['box_volume_sentence_p6']), (37, 'cube-litres-model', 'หาปริมาตรลูกบาศก์เมตรแล้วคูณหนึ่งพันเพื่อเป็นลิตร', ['cube_litres_sentence_p6']), (38, 'inverse-box-model', 'เปลี่ยนหน่วยให้ตรงกับปริมาตรก่อนหารด้วยผลคูณอีกสองมิติ', ['box_dimension_sentence_p6']), (39, 'inverse-box-model', 'เปลี่ยนหน่วยให้ตรงกับปริมาตรก่อนหารด้วยผลคูณอีกสองมิติ', ['box_dimension_sentence_p6']), (40, 'mixed-volume-cost', 'แปลงทุกมิติเป็นเมตรแล้วคูณปริมาตรด้วยราคาต่อลูกบาศก์เมตร', ['mixed_box_cost_sentence_p6'])])]

def main():
    claims=[]
    for slug,topic,items in GROUPS:
        units={}
        for number,key,statement,covered in items:
            source={'sheet':SOURCES[number>20],'item':number-20 if number>20 else number}
            claims.append((source['sheet'],source['item']))
            if key not in units:
                units[key]=dict(id='math.primary6.'+key,kind='procedure',title=statement,statement=statement,
                    steps=['ระบุข้อมูลและสิ่งที่ถาม',statement,'ตรวจหน่วยและแทนคำตอบกลับในความสัมพันธ์'],
                    sources=[],covered_by=['math.'+k for k in covered])
            units[key]['sources'].append(source)
        write_topic(ROOT/f'otk/knowledge/math/primary6-{slug}.json',topic,list(units.values()),'ป.6')
    assert len(claims)==len(set(claims))==40
    assert set(claims)=={(p,n) for p in SOURCES for n in range(1,21)}

if __name__=='__main__':
    main()
